IY_RELOAD_INSTANCE_STATE.TrackConnection = function(connection)
    if connection then
        IY_RELOAD_INSTANCE_STATE.connections[#IY_RELOAD_INSTANCE_STATE.connections + 1] = connection
    end
    return connection
end

